func saveInvestigateConfig(ctx context.Context, cfg *settings.InvestigateConfig) error {
	localPath, err := paths.AbsPath(ctx, settings.EntireSettingsLocalFile)
	if err != nil {
		localPath = settings.EntireSettingsLocalFile
	}

