225	func newFixSubcommand(deps Deps) *cobra.Command {
226		return &cobra.Command{
227			Use:   "fix [run-id]",
228			Short: "Launch a coding agent with a saved investigation as grounded context",
229			Args: func(_ *cobra.Command, args []string) error {
230				if len(args) > 1 {
231					return fmt.Errorf("accepts at most one run id, received %d", len(args))
232				}
233				return nil
234			},
235			RunE: func(cmd *cobra.Command, args []string) error {
236				ctx := cmd.Context()
237				if _, err := paths.WorktreeRoot(ctx); err != nil {
238					cmd.SilenceUsage = true
239					fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Run `entire enable` first.")
240					return wrapSilent(deps.NewSilentError, errors.New("not a git repository"))
241				}
242				store, err := NewLocalManifestStore(ctx)
243				if err != nil {
244					return fmt.Errorf("open manifest store: %w", err)
245				}
246				runID := ""
247				if len(args) == 1 {
248					runID = args[0]
249				}
250				launch := deps.LaunchFix
251				if launch == nil {
